selector_to_html = {"a[href=\"#pyskyfire.common.section_geometry.offset_squared_boundary\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry.offset_squared_boundary\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">offset_squared_boundary</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">floor</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">floor_thickness</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof_thickness</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">side_thickness</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Offset each surface normally and intersect it with the offset sides.</p><p>Thicknesses are normal distances in this section plane. Corners are\nintersections (mitres), so unequal floor and roof thicknesses are allowed.</p></dd>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.common.section_geometry.arc_boundary_metrics\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry.arc_boundary_metrics\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">arc_boundary_metrics</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inner</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">outer</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transform</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Area, centroid, and edge lengths of arc/line/arc/line boundaries.</p><p>Green\u2019s theorem integrates the actual arcs, without a polygon-resolution\ndependency. An optional linear transform maps the section into the\ncoolant-normal plane before measuring it.</p></dd>", "a[href=\"#pyskyfire.common.section_geometry.rounded_width_boundary\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry.rounded_width_boundary\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">rounded_width_boundary</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">floor_width</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof_width</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">height</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">height_input</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'full'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">side_angle</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Two circular lobes joined tangentially, specified by endpoint chords.</p><p>With full height, choose the solution with the smaller sidewall angle\n(larger separation of lobe centres). Sector construction supplies its\nknown angle explicitly, including the zero-length-side circular limit.</p></dd>", "a[href=\"#pyskyfire.common.section_geometry.rounded_boundary\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry.rounded_boundary\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">rounded_boundary</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">prof</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">base_height</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"SectionEllipseArc.html#pyskyfire.common.section_geometry.SectionEllipseArc\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry.SectionEllipseArc\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">SectionEllipseArc</span></span></dt><dd><p>Elliptical boundary, with the same sampling API as a circular arc.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">semi_x</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">semi_y</span></code> are the semi-axes along the section plane\u2019s own\ntwo axes, so equal semi-axes reproduce a <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">SectionArc</span></code> exactly. The\nangles are the ellipse\u2019s parameter, not the polar angle to the point: a\npoint sits at <code class=\"docutils literal notranslate\"><span class=\"pre\">center</span> <span class=\"pre\">+</span> <span class=\"pre\">(semi_x*cos(t),</span> <span class=\"pre\">semi_y*sin(t))</span></code>.</p></dd>", "a[href=\"#pyskyfire.common.section_geometry.rounded_center_distance\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry.rounded_center_distance\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">rounded_center_distance</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">target_area</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">half_angle</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">liner</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Solve the lobe-center distance for an allocated gas-sector area.</p></dd>", "a[href=\"#pyskyfire.common.section_geometry.boundary_surfaces\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry.boundary_surfaces\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">boundary_surfaces</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">floor</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Four directed surfaces, in floor/right/roof/left integration order.</p></dd>", "a[href=\"#pyskyfire.common.section_geometry.surface_lengths\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry.surface_lengths\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">surface_lengths</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">surface</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fraction</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transform</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Length of a centred fraction of physical surface length [m].</p></dd>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"SectionArc.html#pyskyfire.common.section_geometry.SectionArc\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry.SectionArc\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">SectionArc</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.common.section_geometry._WEIGHTS\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry._WEIGHTS\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">_WEIGHTS</span></span></dt><dd></dd>", "a[href=\"#module-pyskyfire.common.section_geometry\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.section_geometry<a class=\"headerlink\" href=\"#module-pyskyfire.common.section_geometry\" title=\"Link to this heading\">\u00b6</a></h1><p>Planar arc geometry used by section analytics and physical construction.</p>", "a[href=\"SectionLine.html#pyskyfire.common.section_geometry.SectionLine\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry.SectionLine\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">SectionLine</span></span></dt><dd><p>Directed straight boundary, with the same sampling API as an arc.</p></dd>", "a[href=\"#pyskyfire.common.section_geometry.rounded_gas_sector_area\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry.rounded_gas_sector_area\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">rounded_gas_sector_area</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">center_distance</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">half_angle</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">liner</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Gas area inside one tube sector in its unprojected section plane.</p><p>The main tube\u2019s exterior is tangent to both sector rays. A liner extends\nits gas-facing arc inward; the neighboring arcs meet on the sector rays.</p></dd>", "a[href=\"#pyskyfire.common.section_geometry.squared_width_boundary\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry.squared_width_boundary\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">squared_width_boundary</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">floor_width</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof_width</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">height</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">radius</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">floor</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Internal chord widths, with floor/roof midpoints separated by height.</p><p>The floor arc has radius <code class=\"docutils literal notranslate\"><span class=\"pre\">radius</span></code> and the roof arc <code class=\"docutils literal notranslate\"><span class=\"pre\">radius</span> <span class=\"pre\">+</span> <span class=\"pre\">height</span></code>.\nInfinite radius represents a line exactly, without evaluating inf * 0.</p></dd>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.common.section_geometry._NODES\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry._NODES\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">_NODES</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.common.section_geometry.squared_boundary\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.section_geometry.squared_boundary\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.section_geometry.</span></span><span class=\"sig-name descname\"><span class=\"pre\">squared_boundary</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">prof</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">sidewall_half_thickness</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
